CREATE TABLE IF NOT EXISTS "consent_sessions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES organizations(id) ON DELETE cascade, "website_id" uuid NOT NULL REFERENCES websites(id) ON DELETE cascade, "consent_record_id" uuid REFERENCES consent_records(id) ON DELETE set null, "policy_version_id" uuid NOT NULL REFERENCES consent_policy_versions(id) ON DELETE restrict, "token_hash" varchar(64) NOT NULL UNIQUE, "status" varchar(20) NOT NULL DEFAULT 'active', "decision_count" integer NOT NULL DEFAULT 0, "expires_at" timestamptz NOT NULL, "revoked_at" timestamptz, "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "privacy_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES organizations(id) ON DELETE cascade, "website_id" uuid NOT NULL REFERENCES websites(id) ON DELETE cascade, "session_id" uuid REFERENCES consent_sessions(id) ON DELETE set null, "event_type" varchar(80) NOT NULL, "provenance" varchar(20) NOT NULL DEFAULT 'observed', "payload" jsonb NOT NULL DEFAULT '{}'::jsonb, "occurred_at" timestamptz NOT NULL DEFAULT now(), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS consent_sessions_org_site_idx ON consent_sessions(organization_id, website_id); CREATE INDEX IF NOT EXISTS privacy_events_org_time_idx ON privacy_events(organization_id, occurred_at);
ALTER TABLE consent_evidence_snapshots ADD COLUMN IF NOT EXISTS proof_version integer NOT NULL DEFAULT 1;
ALTER TABLE consent_evidence_snapshots ADD COLUMN IF NOT EXISTS proof_key_id varchar(64) NOT NULL DEFAULT 'legacy';
